private void moveAllListNodes(DoublyLinkedList<E> list) {
    // If the source list is empty or null, nothing to do
    if (list == null || list.head.next == list.tail) {
        return;
    }
    // Capture the first and last real nodes from the source list
    ListNodeImpl<E> first = list.head.next;
    ListNodeImpl<E> last = list.tail.prev;
    // Attach the source nodes to the tail of this list
    this.tail.prev.next = first;
    first.prev = this.tail.prev;
    // Link the last node to this list's tail sentinel
    last.next = this.tail;
    this.tail.prev = last;
    // Clear the source list by resetting its sentinels
    list.head.next = list.tail;
    list.tail.prev = list.head;
