                if (descriptor.charAt(pos) == 'L') {
                    pos++;
                    while (descriptor.charAt(pos) != ';') pos++;
                    pos++; // skip ';'
                } else {
                    pos++; // primitive type
                }
                outputFrame.pop();
            } else {
                // single primitive type
                outputFrame.pop();
                pos++;
            }
        }
        pos++; // skip ')'
        // ignore return type
    } else {
        // descriptor represents a single type
        char c = descriptor.charAt(pos);
        if (c == 'L') {
            outputFrame.pop();
            pos++;
            while (descriptor.charAt(pos) != ';') pos++;
            pos++; // skip ';'
        } else if (c == '[') {
